BUILTIN_JOBS.push({"file": "susu", "code": "(function () {\n  const CYAN = [0.2, 0.9, 1];\n  const DOWN_TICKS = 100;    // 전투불능 5초\n  const LOCK_TICKS = 60;     // 부활 후 삼각형의 한 꼭짓점 불가 3초\n  const BOLT_SPEED = 1.3;    // 120° · 60° 투사체 속도 (틱당 칸)\n  const BOLT_LIFE = 50;      // 최대 비행 2.5초\n  const HOMING_TICKS = 10;   // 120° 머리 유도 0.5초\n  const HOMING_RANGE = 15;   // 유도 탐색 반경\n  const HEAD_Y = 1.4;        // 발 위치에서 이 높이 이상이면 헤드샷\n\n  function say(api, p, text) { api.actionbar(p, text); }\n\n  function norm(v) {\n    const l = Math.hypot(v.x, v.y, v.z) || 1;\n    return { x: v.x / l, y: v.y / l, z: v.z / l };\n  }\n\n  // 삼각형 모양 링 잔상 (선 3개)\n  function tri(api, x, y, z, r, col) {\n    const pts = [0, 1, 2].map((i) => {\n      const a = Math.PI / 2 + (i * Math.PI * 2) / 3;\n      return { x: x + Math.cos(a) * r, y: y, z: z + Math.sin(a) * r };\n    });\n    for (let i = 0; i < 3; i++) api.line(pts[i], pts[(i + 1) % 3], col, 0.3);\n  }\n\n  // 전투불능: 5초 · 이동 매우 느림 · 나약함 · 발광(벽 너머로 보임)\n  function enterDown(p, api) {\n    p.st.down = api.tick() + DOWN_TICKS;\n    api.effect(p, 'slowness', 5, 5);\n    api.effect(p, 'weakness', 3, 5);\n    api.effect(p, 'glowing', 1, 5);\n    api.title(p, '§c전투불능', '§7절반 조각기만 사용 가능 (5초)');\n    api.particles('dust', p.x, p.y + 1, p.z, 10, [0.5, 0.5, 0.6]);\n  }\n\n  function endDown(p, api) {\n    p.st.down = null;\n    api.clearEffect(p, 'slowness');\n    api.clearEffect(p, 'weakness');\n    api.clearEffect(p, 'glowing');\n  }\n\n  // 각도가 0°면 전투불능, 각도가 생기면 해제\n  function checkDown(p, api) {\n    const st = p.st;\n    const empty = st.angle <= 0;\n    if (empty && !st.down) {\n      enterDown(p, api);\n    } else if (!empty && st.down) {\n      endDown(p, api);\n      say(api, p, '§b전투불능 해제');\n    }\n  }\n\n  // (x, y, z) 지점에 적이 있는지 직접 판정 (몸통 반경 0.65, 높이 -0.2 ~ 2.0)\n  function hitAt(p, api, x, y, z) {\n    const list = api.enemiesAt(p, x, y, z, 2.5);\n    for (const t of list) {\n      const dy = y - t.y;\n      if (dy < -0.2 || dy > 2.0) continue;\n      if (Math.hypot(x - t.x, z - t.z) > 0.65) continue;\n      return { t: t, head: dy >= HEAD_Y };\n    }\n    return null;\n  }\n\n  // 적중 처리: 헤드샷이면 피해 ×1.5\n  function dealHit(p, api, h, dmg) {\n    const final = h.head ? dmg * 1.5 : dmg;\n    api.damage(h.t, final, { by: p, type: 'melee', knockback: 0.3 });\n    api.particles('dust', h.t.x, h.t.y + 1, h.t.z, 8, CYAN);\n    if (h.head) {\n      api.particles('crit', h.t.x, h.t.y + 1.7, h.t.z, 8);\n      say(api, p, '§c헤드샷! §f' + final.toFixed(1));\n    }\n  }\n\n  // 180°: 레이저처럼 즉시 도달 (벽에 막힘) + 맞으면 반경 3칸 폭발\n  function fireLaser(p, api, dmg) {\n    const eye = api.eye(p), d = api.look(p);\n    let x = eye.x + d.x * 0.5, y = eye.y - 0.2 + d.y * 0.5, z = eye.z + d.z * 0.5;\n    const start = { x: x, y: y, z: z };\n    let end = null, hit = null;\n    for (let i = 0; i < 120; i++) {\n      x += d.x * 0.5; y += d.y * 0.5; z += d.z * 0.5;\n      const blk = api.blockAt(x, y, z);\n      if (blk && blk.solid) { end = { x: x, y: y, z: z }; break; }\n      const h = hitAt(p, api, x, y, z);\n      if (h) { hit = h; end = { x: x, y: y, z: z }; break; }\n    }\n    if (!end) end = { x: x, y: y, z: z };\n    api.line(start, end, CYAN, 0.3);\n    api.particles('glow', end.x, end.y, end.z, 6, CYAN);\n    if (hit) {\n      dealHit(p, api, hit, dmg);\n      api.ring(end.x, end.y - 0.5, end.z, 3, CYAN, 32);\n      api.explode(p, end.x, end.y, end.z, 3, 3, { knockback: 0.8, falloff: false, self: false, sound: true });\n    }\n  }\n\n  // 120° · 60° 투사체 이동: 120°는 0.5초 동안 머리를 따라가고, 이후 직선\n  function stepBolts(p, api) {\n    const st = p.st;\n    if (!st.bolts || !st.bolts.length) return;\n    for (let i = st.bolts.length - 1; i >= 0; i--) {\n      const b = st.bolts[i];\n      b.age++;\n      let dead = false;\n\n      if (b.homing && b.age <= HOMING_TICKS) {\n        const near = api.enemiesAt(p, b.x, b.y, b.z, HOMING_RANGE);\n        let best = null, bestD = 1e9;\n        for (const t of near) {\n          const d = Math.hypot(t.x - b.x, t.y + 1.6 - b.y, t.z - b.z);\n          if (d < bestD) { best = t; bestD = d; }\n        }\n        if (best) {\n          const want = norm({ x: best.x - b.x, y: best.y + 1.6 - b.y, z: best.z - b.z }); // 머리 쪽\n          const nd = norm({ x: b.dx * 0.65 + want.x * 0.35, y: b.dy * 0.65 + want.y * 0.35, z: b.dz * 0.65 + want.z * 0.35 });\n          b.dx = nd.x; b.dy = nd.y; b.dz = nd.z;\n        }\n      }\n\n      const step = BOLT_SPEED / 2;\n      for (let s = 0; s < 2 && !dead; s++) {\n        const nx = b.x + b.dx * step, ny = b.y + b.dy * step, nz = b.z + b.dz * step;\n        const blk = api.blockAt(nx, ny, nz);\n        if (blk && blk.solid) {\n          api.particles('dust', b.x, b.y, b.z, 6, CYAN);\n          dead = true;\n          break;\n        }\n        const h = hitAt(p, api, nx, ny, nz);\n        if (h) {\n          dealHit(p, api, h, b.dmg);\n          dead = true;\n          break;\n        }\n        b.x = nx; b.y = ny; b.z = nz;\n      }\n\n      if (!dead) api.particles('dust', b.x, b.y, b.z, 3, CYAN);\n      if (b.age > BOLT_LIFE) dead = true;\n      if (dead) st.bolts.splice(i, 1);\n    }\n  }\n\n  APVP.addJob({\n    id: 'susu',\n    name: '수수', icon: '🔺',\n    desc: '딜러형 · 삼각형 각도 게이지',\n    maxHp: 20,\n    speed: 1,\n    kit: ['ss_shot', 'ss_leap', 'ss_half', 'ss_ult'],\n    items: {\n      ss_shot: {\n        type: 'skill', name: '삼각형의 한 꼭짓점', icon: '▲', mc: 'spectral_arrow', cooldown: 3,\n        lore: '각도 60° 소모 · 피해 6 (헤드샷 ×1.5) · 180° 레이저+폭발 / 120° 머리 유도 / 60° 직선',\n        use(p, api) {\n          const st = p.st, now = api.tick();\n          if (st.down) { say(api, p, '§c전투불능 중에는 사용할 수 없습니다'); return false; }\n          if (now < st.lock) {\n            say(api, p, '§7부활 직후에는 사용할 수 없습니다 (' + Math.ceil((st.lock - now) / 20) + '초)');\n            return false;\n          }\n          if (st.angle < 60) { checkDown(p, api); return false; }\n\n          const tier = st.angle >= 180 ? 3 : st.angle >= 120 ? 2 : 1;\n          let dmg = 6;\n\n          // 자해 강화 (선택): 웅크린 채로 쓰면 나에게 3 피해, 대신 피해 +2\n          if (p.sneaking && p.hp > 1) {\n            const self = Math.min(3, p.hp - 1);\n            api.damage(p, self, { by: p, type: 'magic' });\n            dmg += 2;\n            api.particles('red', p.x, p.y + 1, p.z, 6);\n            say(api, p, '§c자해 강화 §f피해 +2');\n          }\n\n          st.angle = Math.max(0, st.angle - 60);\n\n          if (tier === 3) {\n            api.synth({ wave: 'sawtooth', freq: 1200, to: 600, dur: 0.15, vol: 0.4 }, p);\n            fireLaser(p, api, dmg);\n          } else {\n            const eye = api.eye(p), d = api.look(p);\n            st.bolts = st.bolts || [];\n            st.bolts.push({\n              x: eye.x + d.x * 0.5, y: eye.y - 0.2 + d.y * 0.5, z: eye.z + d.z * 0.5,\n              dx: d.x, dy: d.y, dz: d.z, age: 0, dmg: dmg, homing: tier === 2,\n            });\n            api.synth({ wave: 'triangle', freq: 700, to: 1100, dur: 0.15, vol: 0.4 }, p);\n          }\n\n          checkDown(p, api);\n          return true;\n        },\n      },\n      ss_leap: {\n        type: 'skill', name: '삼각 도약', icon: '💠', mc: 'ender_pearl', cooldown: 10,\n        lore: '각도 60° 소모 · 8칸 순간이동 · 180° 신속 2·재생 2·투명화 2 / 120° 신속 1 / 60° 사용 불가',\n        use(p, api) {\n          const st = p.st;\n          if (st.down) { say(api, p, '§c전투불능 중에는 사용할 수 없습니다'); return false; }\n          if (st.angle < 120) { say(api, p, '§c각도가 120° 이상이어야 사용할 수 있습니다'); return false; }\n          const tier = st.angle >= 180 ? 3 : 2;\n\n          const fx = p.x, fy = p.y, fz = p.z;\n          const d = api.blink(p, 8);\n          if (!d || d < 1) { say(api, p, '§7벽에 막혀 이동할 수 없습니다'); return false; }\n\n          st.angle = Math.max(0, st.angle - 60);\n\n          // 도약이 끝난 뒤 효과\n          if (tier === 3) {\n            api.effect(p, 'speed', 2, 2);\n            api.effect(p, 'regeneration', 2, 2);\n            // 투명화 2는 게임에 없는 효과라 구현 메모 참고\n          } else {\n            api.effect(p, 'speed', 1, 2);\n          }\n\n          tri(api, fx, fy + 0.1, fz, 1.3, CYAN);\n          tri(api, p.x, p.y + 0.1, p.z, 1.3, CYAN);\n          api.particles('dust', p.x, p.y + 1, p.z, 8, CYAN);\n          api.synth({ wave: 'sine', freq: 500, to: 1200, dur: 0.2, vol: 0.4 }, p);\n          checkDown(p, api);\n          return true;\n        },\n      },\n      ss_half: {\n        type: 'skill', name: '절반 조각기', icon: '✂️', mc: 'amethyst_shard', cooldown: 15,\n        lore: '현재 체력의 50%만큼 최대 체력 감소 (이번 목숨 동안) · 각도 180° 회복 (체력 6 이상 · 전투불능 중 사용 가능)',\n        use(p, api) {\n          const st = p.st;\n          if (p.hp < 6) { say(api, p, '§c체력이 6 이상이어야 사용할 수 있습니다'); return false; }\n          const cost = p.hp * 0.5;\n          if (p.maxHp() - cost < 4) { say(api, p, '§c최대 체력이 너무 낮아 사용할 수 없습니다'); return false; }\n\n          // 현재 체력의 절반만큼 최대 체력 감소\n          api.addMaxHp(p, -cost);\n          // 현재 체력이 새 최대 체력보다 높으면 최대 체력까지만 남김\n          const excess = p.hp - p.maxHp();\n          if (excess > 0) api.damage(p, excess, { by: p, type: 'magic' });\n\n          st.angle = 180;\n          checkDown(p, api);\n          api.particles('dust', p.x, p.y + 1, p.z, 12, CYAN);\n          api.synth({ wave: 'triangle', freq: 300, to: 900, dur: 0.3, vol: 0.4 }, p);\n          say(api, p, '§b절반 조각기 §c최대 체력 -' + cost.toFixed(1) + ' §f각도 180°');\n          return true;\n        },\n      },\n      ss_ult: {\n        type: 'skill', name: '일루미나티 파워', icon: '👁️', mc: 'end_crystal', cooldown: 20,\n        lore: '모든 각도 소모 · 즉시 전투불능 · 40칸 안 모든 적에게 피할 수 없는 4 피해 + 구속 II · 나는 재생 III 3초 · 맞은 인원당 최대 체력 +4',\n        use(p, api) {\n          const st = p.st;\n          if (st.down) { say(api, p, '§c전투불능 중에는 사용할 수 없습니다'); return false; }\n          if (st.angle <= 0) { say(api, p, '§c각도가 없습니다'); return false; }\n          const list = api.enemies(p, 40);\n          if (!list.length) { say(api, p, '§7주변에 적이 없습니다'); return false; }\n\n          api.synth({ wave: 'sawtooth', freq: 200, to: 800, dur: 0.5, vol: 0.5 }, p);\n          tri(api, p.x, p.y + 0.1, p.z, 2.5, CYAN);\n          tri(api, p.x, p.y + 2.2, p.z, 1.5, CYAN);\n\n          let n = 0;\n          for (const t of list) {\n            // 피할 수 없는 투사체: 벽과 상관없이 즉시 명중\n            api.line({ x: p.x, y: p.y + 1.5, z: p.z }, { x: t.x, y: t.y + 1, z: t.z }, CYAN, 0.6);\n            api.damage(t, 4, { by: p, type: 'magic' });\n            api.particles('dust', t.x, t.y + 1, t.z, 8, CYAN);\n            if (t.kind !== 'mob') {\n              api.effect(t, 'slowness', 2, 3); // Darkness 3초는 게임에 없어서 구현 메모 참고\n              n++;\n            }\n          }\n\n          if (n > 0) api.addMaxHp(p, 4 * n); // 맞은 인원당 최대 체력 +4\n          api.effect(p, 'regeneration', 3, 3); // 재생 III 3초\n          api.title(p, '§b일루미나티 파워', '§f적 ' + n + '명 명중 · 최대 체력 +' + (4 * n) + ' · 재생 III');\n\n          // 모든 각도를 사용하고 즉시 전투불능\n          st.angle = 0;\n          checkDown(p, api);\n          return true;\n        },\n      },\n    },\n\n    tick(p, api) {\n      const st = p.st, now = api.tick();\n      if (st.angle === undefined) { st.angle = 180; st.lock = now + LOCK_TICKS; }\n\n      // ── 투사체 이동 (120° 유도 후 직선 / 60° 직선) ──\n      stepBolts(p, api);\n\n      // ── 전투불능: 5초 뒤 각도 자동 회복 ──\n      if (st.down && now >= st.down) {\n        st.angle = 180;\n        endDown(p, api);\n        say(api, p, '§b삼각형 재정렬 §f각도 180°');\n      }\n\n      // ── 각도 표시 (머리 위 입자: 60°당 1개) ──\n      if (now % 5 === 0) {\n        const n = Math.ceil(Math.max(0, st.angle) / 60);\n        for (let i = 0; i < n; i++) {\n          const a = now * 0.1 + (i * Math.PI * 2) / 3;\n          api.particles('dust', p.x + Math.cos(a) * 0.6, p.y + 2.3, p.z + Math.sin(a) * 0.6, 1, CYAN);\n        }\n      }\n\n      // ── 게이지 표시 ──\n      if (now % 10 === 0) {\n        const segs = Math.ceil(Math.max(0, st.angle) / 60);\n        let bar = '§b' + '■'.repeat(segs) + '§8' + '■'.repeat(3 - segs) + ' §f' + Math.round(st.angle) + '°';\n        if (st.angle >= 180) bar += ' §b[레이저]';\n        else if (st.angle >= 120) bar += ' §e[유도]';\n        else if (st.angle >= 60) bar += ' §7[직선]';\n        const pct = Math.min(36, Math.max(0, (180 - st.angle) / 5));\n        if (pct > 0) bar += ' §7(피해 -' + Math.round(pct) + '%)';\n        if (st.down) bar += ' §c전투불능 ' + Math.ceil((st.down - now) / 20) + '초';\n        else if (now < st.lock) bar += ' §7사격 잠김 ' + Math.ceil((st.lock - now) / 20) + '초';\n        say(api, p, bar);\n      }\n    },\n\n    // 패시브: 삼각형의 무게중심 — 받는 피해가 (180 - 각도) / 5 % 감소 (최대 36%)\n    hurt(p, amount, src, api) {\n      if (!p.alive || p.hp <= 0) return;\n      if (!src || src.by == null || src.by === p.id) return; // 환경 · 자해 피해는 제외\n      const st = p.st;\n      if (st.angle === undefined) return;\n      const pct = Math.min(36, Math.max(0, (180 - st.angle) / 5));\n      if (pct > 0) api.heal(p, amount * pct / 100);\n    },\n\n    respawn(p, api) {\n      p.st.angle = 180;\n      p.st.lock = api.tick() + LOCK_TICKS;\n      say(api, p, '§b수수 §7- 각도 180° (3초 뒤 삼각형의 한 꼭짓점 사용 가능)');\n    },\n\n    bot(p, t, dist, api) {\n      const st = p.st;\n      if (st.down && p.hp >= 10) api.useItem(p, 'ss_half');\n      if (dist < 35 && (st.angle || 0) >= 180 && p.hp >= 14) api.useItem(p, 'ss_ult');\n      if (dist < 40) api.useItem(p, 'ss_shot');\n      if (dist > 12 && (st.angle || 0) >= 120) api.useItem(p, 'ss_leap');\n      if ((st.angle || 0) <= 60 && p.hp >= 10) api.useItem(p, 'ss_half');\n    },\n  });\n})();", "snd": {}});
